// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {PancakeV1HolderDistributionVault} from "./PancakeV1HolderDistributionVault.sol";

/// @notice Non-upgradeable holder-mode token. The launch factory binds its
/// vault once, then mints the fixed supply; every later balance change is
/// checkpointed before ERC20 state changes.
contract PancakeV1HolderToken is ERC20 {
    uint256 public constant TOTAL_SUPPLY = 1_000_000_000 ether;
    address public immutable launchpad;
    address public immutable factory;
    address public immutable mintRecipient;
    address public immutable poolManager;
    address public immutable positionManager;
    address public immutable locker;
    address public immutable initialBuyRecipient;
    uint256 public immutable launchBlock;
    uint256 public immutable restrictionsEndBlock;
    string private _metadataURI;
    bytes32 public immutable metadataHash;
    PancakeV1HolderDistributionVault public holderVault;
    bool public minted;

    error InvalidConfiguration();
    error VaultAlreadyBound();
    error OnlyLaunchpad();
    error LaunchBlockRestricted();
    error BuyCapExceeded();
    error HoldCapExceeded();

    constructor(
        string memory name_,
        string memory symbol_,
        string memory metadataURI_,
        bytes32 metadataHash_,
        address launchpad_,
        address poolManager_,
        address positionManager_,
        address locker_,
        address initialBuyRecipient_,
        address mintRecipient_,
        uint256 protectionBlocks_
    ) ERC20(name_, symbol_) {
        if (bytes(name_).length == 0 || bytes(symbol_).length == 0 || launchpad_ == address(0)
            || poolManager_ == address(0) || positionManager_ == address(0) || locker_ == address(0)) {
            revert InvalidConfiguration();
        }
        launchpad = launchpad_;
        factory = msg.sender;
        mintRecipient = mintRecipient_;
        poolManager = poolManager_;
        positionManager = positionManager_;
        locker = locker_;
        initialBuyRecipient = initialBuyRecipient_;
        launchBlock = block.number;
        restrictionsEndBlock = block.number + protectionBlocks_;
        _metadataURI = metadataURI_;
        metadataHash = metadataHash_;
    }

    function metadataURI() external view returns (string memory) { return _metadataURI; }
    function tokenURI() external view returns (string memory) { return _metadataURI; }

    function bindVaultAndMint(PancakeV1HolderDistributionVault vault_) external {
        if (msg.sender != launchpad && msg.sender != factory) revert OnlyLaunchpad();
        if (minted || address(vault_) == address(0) || vault_.projectToken() != address(this)) {
            revert VaultAlreadyBound();
        }
        holderVault = vault_;
        minted = true;
        _mint(mintRecipient, TOTAL_SUPPLY);
    }

    function _update(address from, address to, uint256 value) internal override {
        if (address(holderVault) == address(0)) revert InvalidConfiguration();
        holderVault.checkpoint(from, to, value);
        if (restrictionsEndBlock > launchBlock && block.number <= restrictionsEndBlock && from != address(0) && to != address(0)
            && to != poolManager && to != positionManager && to != locker && to != launchpad) {
            if (from == poolManager) {
                if (block.number == launchBlock && to != initialBuyRecipient) revert LaunchBlockRestricted();
                if (value > 55_000_000 ether) revert BuyCapExceeded();
            }
            if (balanceOf(to) + value > 50_000_000 ether) revert HoldCapExceeded();
        }
        super._update(from, to, value);
    }
}

contracts/pancake-v1/PancakeV1InfinityCr.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {PancakeV1InfinityToken} from "./PancakeV1InfinityToken.sol";
import {PancakeV1HolderToken} from "./PancakeV1HolderToken.sol";
import {PancakeV1PermanentPositionLock} from "./PancakeV1PermanentPositionLock.sol";
import {PancakeV1HolderDistributionVault} from "./PancakeV1HolderDistributionVault.sol";
contract PancakeV1InfinityCreationDeployers {
    address public immutable admin;
    address public engine;
    address public immutable positionManager;
    address public immutable tokenLaunchpad;
    address public immutable vault;
    error Unauthorized();
    error AlreadyBound();
    constructor(address admin_,address p,address l,address v){
        require(admin_ != address(0));
        admin=admin_; positionManager=p; tokenLaunchpad=l; vault=v;
    }
    function bindEngine(address engine_) external {
        if (msg.sender != admin || engine != address(0) || engine_ == address(0)) revert Unauthorized();
        engine = engine_;
    }
    function lock(bytes32 salt) external returns(address) {
        if (msg.sender != engine || engine == address(0)) revert Unauthorized();
        return address(new PancakeV1PermanentPositionLock{salt:salt}(positionManager));
    }
    function predictLock(bytes32 salt) external view returns(address) {
        bytes32 h=keccak256(abi.encodePacked(type(PancakeV1PermanentPositionLock).creationCode,abi.encode(positionManager)));
        return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff),address(this),salt,h)))));
    }
    function standard(bytes32 salt,string calldata n,string calldata s,string calldata u,bytes32 h,
        address locker,address creator,address mintTo,uint256 blocks_) external returns(address) {
        if (msg.sender != engine || engine == address(0)) revert Unauthorized();
        return address(new PancakeV1InfinityToken{salt:salt}(
            n,s,u,h,tokenLaunchpad,vault,positionManager,locker,creator,mintTo,blocks_));
    }
    function predictStandard(bytes32 salt,string calldata n,string calldata s,string calldata u,bytes32 h,
        address locker,address creator,address mintTo,uint256 blocks_) external view returns(address) {
        bytes32 initHash = keccak256(abi.encodePacked(type(PancakeV1InfinityToken).creationCode,
            abi.encode(n,s,u,h,tokenLaunchpad,vault,positionManager,locker,creator,mintTo,blocks_)));
        return _create2(salt, initHash);
    }
    function holder(bytes32 salt,string calldata n,string calldata s,string calldata u,bytes32 h,
        address locker,address creator,address mintTo,uint256 blocks_) external returns(address) {
        if (msg.sender != engine || engine == address(0)) revert Unauthorized();
        return address(new PancakeV1HolderToken{salt:salt}(
            n,s,u,h,tokenLaunchpad,vault,positionManager,locker,creator,mintTo,blocks_));
    }
    function predictHolder(bytes32 salt,string calldata n,string calldata s,string calldata u,bytes32 h,
        address locker,address creator,address mintTo,uint256 blocks_) external view returns(address) {
        bytes32 initHash = keccak256(abi.encodePacked(type(PancakeV1HolderToken).creationCode,
            abi.encode(n,s,u,h,tokenLaunchpad,vault,positionManager,locker,creator,mintTo,blocks_)));
        return _create2(salt, initHash);
    }
    function bind(address token, address vault_) external {
        if (msg.sender != engine || engine == address(0)) revert Unauthorized();
        PancakeV1HolderToken(token).bindVaultAndMint(PancakeV1HolderDistributionVault(vault_));
    }
    function _create2(bytes32 salt, bytes32 initHash) private view returns(address) {
        return address(uint160(uint256(keccak256(abi.encodePacked(
            bytes1(0xff), address(this), salt, initHash
        )))));
    }
}

contracts/pancake-v1/PancakeV1InfinityHo.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice Narrow ABI-compatible Pancake Infinity CL types.  These are
/// intentionally vendored because the application does not pin the upstream
/// Infinity package as a Solidity dependency.
type PancakeV1Currency is address;
type PancakeV1BeforeSwapDelta is int256;
type PancakeV1BalanceDelta is int256;

interface IPancakeV1Hooks {
    function getHooksRegistrationBitmap() external view returns (uint16);
}

interface IPancakeV1CLPoolManager {
    struct SwapParams {
        bool zeroForOne;
        int256 amountSpecified;
        uint160 sqrtPriceLimitX96;
    }

    function vault() external view returns (address);
    function getSlot0(bytes32 poolId)
        external view returns (uint160 sqrtPriceX96, int24 tick, uint24 protocolFee, uint24 lpFee);
    function swap(
        PancakeV1PoolKey calldata key,
        SwapParams calldata params,
        bytes calldata hookData
    ) external returns (PancakeV1BalanceDelta delta);
}

interface IPancakeV1Vault {
    function manager() external view returns (address);
    function lock(bytes calldata data) external returns (bytes memory);
    function currencyDelta(address settler, PancakeV1Currency currency) external view returns (int256);
    function getUnsettledDeltasCount() external view returns (uint256);
    function sync(PancakeV1Currency currency) external;
    function settleFor(address recipient) external payable returns (uint256);
    function take(PancakeV1Currency currency, address to, uint256 amount) external;
}

interface IPancakeV1LockCallback {
    function lockAcquired(bytes calldata data) external returns (bytes memory);
}

interface IPancakeV1FeeReceiver {
    function recordFee(address asset, uint256 amount) external;
}

struct PancakeV1PoolKey {
    PancakeV1Currency currency0;
    PancakeV1Currency currency1;
    IPancakeV1Hooks hooks;
    IPancakeV1CLPoolManager poolManager;
    uint24 fee;
    bytes32 parameters;
}

library PancakeV1BalanceDeltaLib {
    function amount0(PancakeV1BalanceDelta delta) internal pure returns (int128 value) {
        assembly ("memory-safe") { value := sar(128, delta) }
    }

    function amount1(PancakeV1BalanceDelta delta) internal pure returns (int128 value) {
        assembly ("memory-safe") { value := signextend(15, delta) }
    }
}

library PancakeV1BeforeSwapDeltaLib {
    function toDelta(int128 specified, int128 unspecified)
        internal pure returns (PancakeV1BeforeSwapDelta value) {
        assembly ("memory-safe") {
            value := or(shl(128, specified), and(sub(shl(128, 1), 1), unspecified))
        }
    }
}

